ALTER TABLE public.projects ADD COLUMN organization_type text NOT NULL DEFAULT 'individual', ADD COLUMN organization_name text NOT NULL DEFAULT '', ADD COLUMN ai_consent boolean NOT NULL DEFAULT false, ADD COLUMN code_consent boolean NOT NULL DEFAULT false, ADD COLUMN test_consent boolean NOT NULL DEFAULT false, ADD COLUMN fix_consent boolean NOT NULL DEFAULT false, ADD COLUMN consent_at timestamptz;
ALTER TABLE public.projects ADD CONSTRAINT projects_organization_type CHECK (organization_type IN ('individual', 'private', 'public'));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['projects','audit_runs','claims','test_results','findings','fix_proposals','evidence','tool_calls'] LOOP IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t); END IF; END LOOP; END $$;